(()=>{const nav=document.querySelector('.coffee-divisions');const buttons=[...nav.querySelectorAll('button')];const groups=[...document.querySelectorAll('.coffee-division')];function select(i){buttons.forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});groups.forEach((g,j)=>g.hidden=i!==j);requestAnimationFrame(()=>{const h=groups[i].querySelector('h2');const inset=Math.max(0,parseFloat(getComputedStyle(nav).top)||0);window.scrollTo({top:Math.max(0,h.getBoundingClientRect().top+scrollY-nav.getBoundingClientRect().height-inset-16),behavior:'instant'})})}buttons.forEach((b,i)=>b.addEventListener('click',()=>select(i)));nav.addEventListener('keydown',e=>{let i=buttons.findIndex(b=>b.getAttribute('aria-selected')==='true');if(e.key==='ArrowRight')i=(i+1)%4;else if(e.key==='ArrowLeft')i=(i+3)%4;else if(e.key==='Home')i=0;else if(e.key==='End')i=3;else return;e.preventDefault();select(i);buttons[i].focus({preventScroll:true})})})();
document.querySelectorAll('.coffee-feature a').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').split('#')[1],target=document.getElementById(id);if(target){e.preventDefault();target.scrollIntoView({behavior:'instant',block:'start'})}}));
